import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheet, type Sheet } from '../session/session';

/** The sheet's today: shown, and changeable. Changing it re-reads the whole sheet. */
function SheetToday({ sheetId, user }: { sheetId: string; user: string }) {
  const sheet = useSheet(sheetId);
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today, by: user }),
    onSuccess: (saved) => {
      queryClient.setQueryData(['sheet', sheetId], saved);
      void queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onSettled: submit.end,
  });
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        save.mutate(typed.trim());
      }}
    >
      Today <span data-testid="sheet-today">{sheet.data?.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={typed}
        onChange={(e) => {
          setTyped(e.target.value);
          save.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      {save.isError && <span data-testid="sheet-error">Could not change today.</span>}
    </form>
  );
}

export const contribution = SheetPage.fill({ order: 0, Component: SheetToday });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

// Who is signed in and which sheet is active live in the URL (`user`, `sheet`), so any feature
// reads them directly. There is no password: signing in is typing a name.
export const useUser = () => useSearchParam('user', asString);
export const useSheetId = () => useSearchParam('sheet', asString);

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default date on the
 *  sheet uses it, never the browser's clock. */
export type Sheet = { id: string; today: string };

/** The active sheet as the store holds it. Keyed ['sheet', id]: every per-sheet key starts so. */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId],
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
    enabled: sheetId !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or '' while the sheet loads. Use it for every default date. */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's content on the home screen. Rendered once a user is signed in and a sheet is
 * loaded; everything a contribution shows or changes belongs to `sheetId` and is done as `user`.
 */
export const SheetPage = defineSlot<{ sheetId: string; user: string }>('sheet.page');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

